$ErrorActionPreference='Continue'
$root='F:\JericoEngine\JericoEngine';$base=Join-Path $root 'build\n0-validation\local-packages';$freeze=Join-Path $base 'source-freeze-root-python-offline.json';$venv=Join-Path $root 'build\n0-validation\original-engine-deps\Python\venv\31e81382';$python=Join-Path $venv 'Scripts\python.exe';$pyScript=Join-Path $base 'original-engine-python-venv-audit.py';$prefix=Join-Path $base 'original-engine-python-venv-audit';if(-not(Test-Path -LiteralPath $python)){throw "local venv Python missing: $python"}
function FrozenSnapshot{$m=Get-Content -LiteralPath $freeze -Raw|ConvertFrom-Json;$items=@(foreach($i in $m){$p=Join-Path $root $i.path;$h=Get-FileHash -LiteralPath $p -Algorithm SHA256;[pscustomobject]@{path=$i.path;expected=$i.sha256;actual=$h.Hash;match=($h.Hash -eq $i.sha256)}});[pscustomobject]@{freeze_sha256=(Get-FileHash -LiteralPath $freeze -Algorithm SHA256).Hash;files=$items;all_match=(@($items|Where-Object{-not $_.match}).Count -eq 0)}}
$envBefore=[pscustomobject]@{PIP_NO_INDEX=[bool]$env:PIP_NO_INDEX;PIP_CONFIG_FILE=[bool]$env:PIP_CONFIG_FILE;PIP_INDEX_URL=[bool]$env:PIP_INDEX_URL;PIP_EXTRA_INDEX_URL=[bool]$env:PIP_EXTRA_INDEX_URL;PYTHONPATH=[bool]$env:PYTHONPATH;PYTHONHOME=[bool]$env:PYTHONHOME};$env:LY_PACKAGE_SERVER_URLS=$null;$env:PIP_NO_INDEX='1';$env:PIP_CONFIG_FILE='NUL';$env:PIP_DISABLE_PIP_VERSION_CHECK='1';$env:PIP_INDEX_URL=$null;$env:PIP_EXTRA_INDEX_URL=$null;$env:PIP_FIND_LINKS=$null;$env:PIP_TRUSTED_HOST=$null;$env:PYTHONNOUSERSITE='1';$env:PYTHONDONTWRITEBYTECODE='1';$env:PYTHONPATH=$null;$env:PYTHONHOME=$null
$meta=[pscustomobject]@{cwd=(Get-Location).Path;python=$python;python_sha256=(Get-FileHash -LiteralPath $python -Algorithm SHA256).Hash;python_script=$pyScript;python_script_sha256=(Get-FileHash -LiteralPath $pyScript -Algorithm SHA256).Hash;venv=$venv;started=(Get-Date).ToString('o');source_before=(FrozenSnapshot);env_inherited_presence=$envBefore};$meta|ConvertTo-Json -Depth 7|Set-Content -LiteralPath "$prefix-before.json" -Encoding UTF8
$checkArgs=[string[]]@('-I','-B','-m','pip','check');$sw=[Diagnostics.Stopwatch]::StartNew();$checkOutput=& $python @checkArgs 2>&1;$checkExit=$LASTEXITCODE;$checkElapsed=$sw.Elapsed.TotalSeconds;$sw.Stop();$checkOutput|Out-String|Set-Content -LiteralPath "$prefix-pip-check.log" -Encoding UTF8;$checkExit|Set-Content -LiteralPath "$prefix-pip-check.exitcode" -Encoding ASCII;('{0:N3}s' -f $checkElapsed)|Set-Content -LiteralPath "$prefix-pip-check.elapsed.txt" -Encoding ASCII
$listArgs=[string[]]@('-I','-B','-m','pip','list','--format=json');$sw=[Diagnostics.Stopwatch]::StartNew();$listOutput=& $python @listArgs 2>&1;$listExit=$LASTEXITCODE;$listElapsed=$sw.Elapsed.TotalSeconds;$sw.Stop();$listOutput|Out-String|Set-Content -LiteralPath "$prefix-pip-list.json" -Encoding UTF8;$listExit|Set-Content -LiteralPath "$prefix-pip-list.exitcode" -Encoding ASCII;('{0:N3}s' -f $listElapsed)|Set-Content -LiteralPath "$prefix-pip-list.elapsed.txt" -Encoding ASCII
$importArgs=[string[]]@('-I','-B',$pyScript);$sw=[Diagnostics.Stopwatch]::StartNew();$importOutput=& $python @importArgs 2>&1;$importExit=$LASTEXITCODE;$importElapsed=$sw.Elapsed.TotalSeconds;$sw.Stop();$importOutput|Out-String|Set-Content -LiteralPath "$prefix-imports.json" -Encoding UTF8;$importExit|Set-Content -LiteralPath "$prefix-imports.exitcode" -Encoding ASCII;('{0:N3}s' -f $importElapsed)|Set-Content -LiteralPath "$prefix-imports.elapsed.txt" -Encoding ASCII
$after=FrozenSnapshot;$stamps=@(Get-ChildItem -LiteralPath $venv -File -Recurse -Filter '*.stamp'|ForEach-Object{$h=Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256;[pscustomobject]@{path=$_.FullName.Substring($venv.Length+1).Replace('\','/');bytes=$_.Length;sha256=$h.Hash}});$result=[pscustomobject]@{started=$meta.started;finished=(Get-Date).ToString('o');venv=$venv;python_sha256=$meta.python_sha256;source_before=$meta.source_before;source_after=$after;pip_check_exit=$checkExit;pip_check_elapsed_seconds=$checkElapsed;pip_list_exit=$listExit;pip_list_elapsed_seconds=$listElapsed;imports_exit=$importExit;imports_elapsed_seconds=$importElapsed;requirement_stamps=$stamps;python_script_sha256=$meta.python_script_sha256};$result|ConvertTo-Json -Depth 8|Set-Content -LiteralPath "$prefix-result.json" -Encoding UTF8;Write-Output ("pip_check=$checkExit pip_list=$listExit imports=$importExit source_frozen=$($after.all_match)")
